// Stop early with a clear message if Settings still holds the template placeholders.
{
  const s = $('Settings').first().json;
  const unset = ["ownerEmail", "signature", "companyName", "sheetId"].filter(k => !String(s[k] ?? '').trim() || String(s[k]).includes('REPLACE_ME'));
  if (unset.length) {
    throw new Error('Open the Settings node and fill in: ' + unset.join(', ') + '. They still contain REPLACE_ME placeholders.');
  }
}

return $input.all();

// Decide, for every invoice row, whether a reminder is due today.
const s = $('Settings').first().json;
const today = $today; // start of today in the workflow's time zone
const steps = String(s.reminderDays || '1, 7, 14')
  .split(',').map(n => parseInt(n, 10)).filter(n => n >= 0).sort((a, b) => a - b);
const minGap = Number(s.minDaysBetween) || 0;
const dryRun = s.dryRun !== false && String(s.dryRun).toLowerCase() !== 'false';

// Accepts Google Sheets date serial numbers, ISO dates (2026-11-22) and ISO date-times.
function toDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number' || /^\d+(\.\d+)?$/.test(String(v))) {
    return DateTime.fromObject({ year: 1899, month: 12, day: 30 }, { zone: today.zone })
      .plus({ days: Math.floor(Number(v)) });
  }
  const d = DateTime.fromISO(String(v).trim(), { zone: today.zone });
  return d.isValid ? d.startOf('day') : null;
}
function money(amount, currency) {
  const n = Number(String(amount).replace(/[^0-9.\-]/g, ''));
  if (amount === '' || isNaN(n)) return String(amount || '');
  try {
    if (/^[A-Z]{3}$/.test(String(currency))) {
      return new Intl.NumberFormat('en-US', { style: 'currency', currency }).format(n);
    }
  } catch (e) {}
  return `${currency ? currency + ' ' : ''}${n.toFixed(2)}`;
}
const fmt = d => d.toFormat('d LLL yyyy');
const ordinal = ['first', 'second', 'third', 'fourth', 'fifth'];

function reminderText(inv, stage, last) {
  const hi = `Hi ${inv.contactName || inv.client || 'there'},`;
  const ref = `invoice ${inv.invoice} for ${inv.amountText}`;
  const pay = inv.paymentLink ? `You can pay online here: ${inv.paymentLink}` : '';
  const paid = "If you've already paid, thank you, and please ignore this message.";
  let subject, lines;
  if (stage === 1) {
    subject = `Friendly reminder: invoice ${inv.invoice} was due on ${inv.dueText}`;
    lines = [hi, '', `I hope you're well. This is a friendly reminder that ${ref} was due on ${inv.dueText}.`, pay, '', paid, 'If anything is unclear, just reply to this email.'];
  } else if (!last) {
    subject = `Reminder: invoice ${inv.invoice} is ${inv.daysOverdue} days overdue`;
    lines = [hi, '', `I'm following up on ${ref}, which was due on ${inv.dueText} and is now ${inv.daysOverdue} days overdue.`, pay, '', 'Could you let me know when I can expect payment? ' + paid];
  } else {
    subject = `Final reminder: invoice ${inv.invoice} is ${inv.daysOverdue} days overdue`;
    lines = [hi, '', `This is a final reminder about ${ref}, which was due on ${inv.dueText} and is now ${inv.daysOverdue} days overdue.`, pay, '', "Please arrange payment as soon as possible, or reply to let me know if there's a problem with the invoice so we can sort it out together. " + paid];
  }
  const body = [...lines.filter((l, n, a) => l !== '' || a[n - 1] !== ''), '', 'Best regards,', s.signature, s.companyName].join('\n');
  return { subject, body };
}

const out = [];
$input.all().forEach((item, i) => {
  const r = item.json;
  if (Object.keys(r).length === 0) return; // empty sheet
  const status = String(r['Status'] || '').trim();
  if (/^(paid|void|cancel+ed|written off)$/i.test(status)) return;

  const inv = {
    row: r.row_number,
    invoice: String(r['Invoice #'] ?? '').trim(),
    client: String(r['Client'] || '').trim(),
    contactName: String(r['Contact name'] || '').trim(),
    email: String(r['Email'] || '').trim(),
    amountText: money(r['Amount'], String(r['Currency'] || '').trim().toUpperCase()),
    paymentLink: String(r['Payment link'] || '').trim(),
    remindersSent: parseInt(r['Reminders sent'], 10) || 0,
  };
  const due = toDate(r['Due date']);
  const last = toDate(r['Last reminder']);

  const problems = [];
  if (!inv.invoice) problems.push('no Invoice #');
  if (!due) problems.push('Due date missing or not a date');
  if (!/^[^\s@,]+@[^\s@,]+\.[^\s@,]+$/.test(inv.email)) problems.push('Email missing or not valid');
  if (problems.length) {
    // Only report rows that look like real invoices (anything filled in).
    if (inv.invoice || inv.client || inv.email) {
      out.push({ json: { ...inv, action: 'fix', problem: problems.join(', ') }, pairedItem: { item: i } });
    }
    return;
  }

  inv.dueText = fmt(due);
  inv.daysOverdue = Math.floor(today.diff(due, 'days').days);
  if (inv.daysOverdue <= 0) return; // not overdue yet

  const stage = inv.remindersSent + 1;
  const daysSinceLast = last ? Math.floor(today.diff(last, 'days').days) : Infinity;
  let action = 'wait';
  if (inv.remindersSent >= steps.length) action = 'escalate';
  else if (inv.daysOverdue >= steps[inv.remindersSent] && daysSinceLast >= minGap) action = 'remind';

  const json = { ...inv, action, stage, totalStages: steps.length, lastReminder: last ? fmt(last) : '', dryRun };
  if (action === 'remind') {
    const t = reminderText(inv, stage, stage === steps.length && steps.length > 1);
    json.to = dryRun ? s.ownerEmail : inv.email;
    json.subject = (dryRun ? `[TEST, would go to ${inv.email}] ` : '') + t.subject;
    json.body = t.body;
    json.todayIso = today.toFormat('yyyy-MM-dd');
  }
  out.push({ json, pairedItem: { item: i } });
});
return out;

// One summary email for you: what was sent, what needs you, and rows to fix.
const s = $('Settings').first().json;
const all = $input.all().map(i => i.json);
const by = a => all.filter(x => x.action === a);
const sent = by('remind'), escalate = by('escalate'), waiting = by('wait'), fix = by('fix');
if (!sent.length && !escalate.length && !fix.length) return [];

const line = x => `- ${x.invoice} · ${x.client || x.email} · ${x.amountText} · ${x.daysOverdue} days overdue`;
const dryRun = s.dryRun !== false && String(s.dryRun).toLowerCase() !== 'false';
const parts = [
  `Invoice reminders for ${$today.toFormat('cccc d LLL yyyy')}`,
  dryRun ? '\nTEST RUN: reminders were sent to you instead of clients, and the sheet was not changed. Set dryRun to false in Settings when you are happy with them.' : '',
];
if (sent.length) parts.push(`\nReminders ${dryRun ? 'drafted (sent to you)' : 'sent'} (${sent.length}):`, ...sent.map(x => `${line(x)} · reminder ${x.stage} of ${x.totalStages}`));
if (escalate.length) parts.push(`\nNeeds a personal follow-up (${escalate.length}). All automatic reminders have been sent:`, ...escalate.map(x => `${line(x)} · last reminder ${x.lastReminder || 'unknown'}`));
if (waiting.length) parts.push(`\nOverdue, next reminder later (${waiting.length}):`, ...waiting.map(x => `${line(x)} · ${x.remindersSent} sent so far`));
if (fix.length) parts.push(`\nRows to fix in the sheet (${fix.length}):`, ...fix.map(x => `- row ${x.row}${x.invoice ? ' (' + x.invoice + ')' : ''}: ${x.problem}`));
parts.push(`\nSheet: https://docs.google.com/spreadsheets/d/${s.sheetId}`);

return [{
  json: {
    subject: `${dryRun ? '[TEST] ' : ''}Invoice reminders: ${sent.length} sent, ${escalate.length} need you${fix.length ? ', ' + fix.length + (fix.length === 1 ? ' row' : ' rows') + ' to fix' : ''}`,
    body: parts.filter(p => p !== '').join('\n'),
  },
}];
